        sample = _nv(
            '0000:01:00.0,A,16384 MiB,12000 MiB,4384 MiB,U\n',
            when=NOW + timedelta(seconds=30),
        )
        inv = normalize_inventory([sample], now_utc=NOW, max_age_seconds=MAX_AGE)
        self.assertEqual(inv['devices'][0]['freshness_status'], 'STALE')
